begin;
select no_plan();
create function pg_temp.id(n integer) returns uuid language sql immutable as $$select ('cc280000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid$$;
create function pg_temp.login(n integer) returns void language sql as $$select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.id(n),'role','authenticated')::text,true)::void$$;
insert into auth.users(id,email) select pg_temp.id(n),'explainer-'||n||'@test.local' from generate_series(10,15) n;
insert into public.organizations(id,slug,name) values(pg_temp.id(1),'explain-a','A'),(pg_temp.id(2),'explain-b','B');
insert into public.memberships(organization_id,user_id,role) values(pg_temp.id(1),pg_temp.id(10),'owner'),(pg_temp.id(1),pg_temp.id(11),'planner'),(pg_temp.id(1),pg_temp.id(12),'viewer'),(pg_temp.id(1),pg_temp.id(13),'branch_user'),(pg_temp.id(2),pg_temp.id(14),'owner'),(pg_temp.id(1),pg_temp.id(15),'admin');
insert into public.locations(id,organization_id,code,name_en,location_type,country_code,timezone) values(pg_temp.id(20),pg_temp.id(1),'L1','One','branch','SA','Asia/Riyadh'),(pg_temp.id(21),pg_temp.id(1),'L2','Two','branch','SA','Asia/Riyadh');
insert into public.membership_locations values(pg_temp.id(1),pg_temp.id(13),pg_temp.id(20));
insert into public.planning_runs(id,organization_id,location_id,request_id,from_date,to_date,kind,status,options,finished_at,result)
 select pg_temp.id(30+n),pg_temp.id(1),pg_temp.id(20+n),pg_temp.id(40+n),'2026-07-01','2026-10-01','policy','succeeded','{}',now(),'{}' from generate_series(0,1) n;
insert into public.inventory_policies(id,organization_id,run_id,location_id,forecast_id,item_id,item_code,unit,status,summary,evidence)
 select pg_temp.id(50+n),pg_temp.id(1),pg_temp.id(30+n),pg_temp.id(20+n),pg_temp.id(60),pg_temp.id(61),'PART-'||n,'EA','available','{}','{"method": "policy-v1", "options": {"lead_time": 3, "review_interval": 4, "service_level": "0.95"}, "forecast": {"run_id": "cc280000-0000-4000-8000-000000000060", "method": "expanded-v1", "to_date": "2026-10-01", "horizon": 28, "output": {"model": "naive", "forecast": []}, "source": {"private_email": "DO-NOT-SEND@example.com", "unit_cost": "99", "transactions": ["private"]}}, "output": {"status": "available", "lead_time": {"days": 3, "forecast": "3.001", "quantile": "4.125", "target": "4.125", "safety_stock": "1.124"}, "protection": {"days": 7, "forecast": "3.001", "quantile": "4.125", "target": "8.125", "safety_stock": "1.124"}, "residual_count": 84, "positive_days": 90, "samples": 5000, "calibration": [{"private": "DO-NOT-SEND"}]}}'::jsonb from generate_series(0,1) n;

insert into public.planning_runs(id,organization_id,location_id,request_id,from_date,to_date,kind,status,options,result,finished_at)
 select pg_temp.id(90+n),pg_temp.id(1),pg_temp.id(20+n),gen_random_uuid(),'2026-07-01','2026-10-01','forecast','succeeded','{"method":"expanded-v1","horizon":28}','{}',now() from generate_series(0,1) n;
insert into public.forecast_results(id,organization_id,run_id,location_id,item_id,item_code,item_name,status,model,summary,evidence)
 select pg_temp.id(92+n),pg_temp.id(1),pg_temp.id(90+n),pg_temp.id(20+n),pg_temp.id(61),'PART','Part','selected','naive','{}','{"source": {"start_day": "2026-07-01", "end_day": "2026-10-01", "introduced_on": null, "discontinued_on": null, "demand": [["2026-07-01", "99", "1"]], "unit_provenance": {"method": "source-units-v1", "status": "consistent", "unit": "EA", "rows": 1, "unknown_rows": 0, "units": ["EA"]}, "account": "DO-NOT-SEND"}, "output": {"status": "selected", "model": "naive", "total": "28", "scores": [{"model": "naive", "rmse": "1.123456789012345678", "mae": "1", "bias": "-0.25", "folds": [{"rmse": "1", "mae": "1", "bias": "0"}, {"rmse": "1", "mae": "1", "bias": "0"}, {"rmse": "1", "mae": "1", "bias": "0"}]}], "folds": [{"train_from": "2026-07-01", "train_to": "2026-07-09", "test_from": "2026-07-10", "test_to": "2026-08-06"}, {"train_from": "2026-07-01", "train_to": "2026-07-09", "test_from": "2026-07-10", "test_to": "2026-08-06"}, {"train_from": "2026-07-01", "train_to": "2026-07-09", "test_from": "2026-07-10", "test_to": "2026-08-06"}], "forecast": [{"date": "2026-10-02", "quantity": "1"}], "uncertainty": {"status": "available", "residual_count": 84, "bands": []}, "evaluation": {"status": "available", "model": "mean", "train_to": "2026-09-03", "test_from": "2026-09-04", "test_to": "2026-10-01", "count": 28, "calibration": 84, "coverage80": "0.8", "coverage95": "0.95", "forecast": ["DO-NOT-SEND"], "bands": []}}, "driver": {"private": "DO-NOT-SEND"}, "price": "DO-NOT-SEND"}'::jsonb from generate_series(0,1) n;
create function pg_temp.preview() returns jsonb language sql as $$select public.forecast_explainer_preview(pg_temp.id(1),pg_temp.id(92))$$;
create function pg_temp.request(n integer default 70) returns uuid language sql as $$select public.forecast_explainer_request(pg_temp.id(1),pg_temp.id(92),pg_temp.id(n),'Why this model?','en',pg_temp.preview()->>'fingerprint',true)$$;
select pg_temp.login(10);set local role authenticated;
select is(pg_temp.preview()#>>'{evidence,model_comparison,scores,0,rmse}','1.123456789012345678','scores retain exact decimals');
select is(pg_temp.preview()#>>'{evidence,held_out_coverage,model}','mean','held-out model remains separate from selected model');
select ok(position('DO-NOT-SEND' in pg_temp.preview()::text)=0,'nested raw demand, prices and driver data excluded');
select ok(not(pg_temp.preview()->'evidence' ? 'forecast_id'),'provider excludes identifiers');
select throws_ok($$select pg_temp.request()$$,'MQ403',null,'shared opt-in defaults off');
select pg_temp.login(14);
select throws_ok($$select pg_temp.preview()$$,'MQ404',null,'foreign tenant preview denied');
select pg_temp.login(13);
select lives_ok($$select pg_temp.preview()$$,'assigned branch preview allowed');
select throws_ok($$select public.forecast_explainer_preview(pg_temp.id(1),pg_temp.id(93))$$,'MQ404',null,'other branch preview denied');
select throws_ok($$select pg_temp.request()$$,'MQ403',null,'branch cannot request');
select pg_temp.login(12);
select throws_ok($$select pg_temp.request()$$,'MQ403',null,'viewer cannot request');
select pg_temp.login(10);select public.policy_explainer_configure(pg_temp.id(1),true);
select throws_ok($$select public.forecast_explainer_request(pg_temp.id(1),pg_temp.id(92),pg_temp.id(70),'Why?','en',repeat('0',64),true)$$,'MQ409',null,'changed preview rejected');
select throws_ok($$select public.forecast_explainer_request(pg_temp.id(1),pg_temp.id(92),pg_temp.id(70),'Why?','en',pg_temp.preview()->>'fingerprint',false)$$,'MQ422',null,'explicit sharing confirmation required');
create temporary table saved as select pg_temp.request() id;grant select on saved to service_role;
select is(pg_temp.request(),(select id from saved),'forecast retry is stable');
select throws_ok($$select public.policy_explainer_request(pg_temp.id(1),pg_temp.id(50),pg_temp.id(70),'Why this model?','en',pg_temp.preview()->>'fingerprint',true)$$,'MQ409',null,'identity cannot be reused across source kinds');
select throws_ok($$select public.policy_explainer_request(pg_temp.id(1),pg_temp.id(50),pg_temp.id(71),'Why?','en',public.policy_explainer_preview(pg_temp.id(1),pg_temp.id(50))->>'fingerprint',true)$$,'MQ429',null,'forecast attempt consumes shared policy quota');
select throws_ok($$select public.policy_explainer_dispatch((select id from saved),pg_temp.id(10),'claude-sonnet-5-5')$$,'42501',null,'forecast dispatch remains server-only');
reset role;set local role service_role;
select is(public.policy_explainer_dispatch((select id from saved),pg_temp.id(10),'claude-sonnet-5-5')->>'prompt_version','forecast-explainer-v1','forecast prompt version captured');
select is(public.policy_explainer_dispatch((select id from saved),pg_temp.id(10),'claude-sonnet-5-5')->>'dispatch','false','retry never resends forecast');
select throws_ok($$select public.policy_explainer_complete((select id from saved),pg_temp.id(10),'{"paragraphs":[{"text":"bad","references":["policy_inputs"]}]}','claude-sonnet-5-5',null)$$,'MQ422',null,'policy-only reference rejected for forecast');
select lives_ok($$select public.policy_explainer_complete((select id from saved),pg_temp.id(10),'{"paragraphs":[{"text":"Historical RMSE.","references":["model_comparison","held_out_coverage"]}]}','claude-sonnet-5-5',null)$$,'forecast answer accepts only its own sections');
select throws_ok($$select public.policy_explainer_complete((select id from saved),pg_temp.id(10),null,null,'provider_error')$$,'MQ409',null,'terminal forecast immutable');
reset role;set local role authenticated;select pg_temp.login(14);
select is((select count(*) from public.policy_explanations),0::bigint,'other tenant cannot inspect forecasts');
select pg_temp.login(13);
select is((select count(*) from public.policy_explanations),1::bigint,'assigned branch reads forecast');
reset role;delete from public.membership_locations where user_id=pg_temp.id(13);set local role authenticated;
select is((select count(*) from public.policy_explanations),0::bigint,'location revocation removes forecast history');
reset role;update public.forecast_results set evidence=jsonb_set(evidence,'{source,unit_provenance,status}','"unknown"') where id=pg_temp.id(93);
set local role authenticated;select pg_temp.login(10);
select throws_ok($$select public.forecast_explainer_preview(pg_temp.id(1),pg_temp.id(93))$$,'MQ422',null,'unknown units unavailable');
reset role;update public.forecast_results set evidence=jsonb_set(evidence,'{source,unit_provenance,status}','"consistent"') where id=pg_temp.id(93);
update public.planning_runs set options='{"method":"regional-v1","horizon":28}' where id=pg_temp.id(91);
set local role authenticated;
select throws_ok($$select public.forecast_explainer_preview(pg_temp.id(1),pg_temp.id(93))$$,'MQ422',null,'prepared groups excluded');
reset role;update public.planning_runs set options='{"method":"driver-v1","horizon":28}' where id=pg_temp.id(91);
set local role authenticated;
select is(public.forecast_explainer_preview(pg_temp.id(1),pg_temp.id(93))#>>'{evidence,forecast_limits,driver_conditioned}','true','driver forecasts carry availability and uncertainty caveat');
reset role;update public.forecast_results set evidence=evidence #- '{output,evaluation}' #- '{output,uncertainty}' where id=pg_temp.id(93);
set local role authenticated;
select is(public.forecast_explainer_preview(pg_temp.id(1),pg_temp.id(93))#>>'{evidence,held_out_coverage,status}','not_recorded','missing coverage remains unknown');
select public.policy_explainer_configure(pg_temp.id(1),false);
select is(pg_temp.request(),(select id from saved),'completed forecast retry survives opt-out');
reset role;delete from public.planning_runs where id=pg_temp.id(90);set local role authenticated;
select is((select status from public.policy_explanations where id=(select id from saved)),'succeeded','forecast deletion retains saved explanation');
select is((select evidence#>>'{model_comparison,scores,0,rmse}' from public.policy_explanations where id=(select id from saved)),'1.123456789012345678','source deletion keeps copied scores');
reset role;select * from finish();rollback;
